#!/usr/bin/env bash
# Question 5: Unhealthy Deployment ${Q5_APP}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q5_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q5_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: ConfigMap
metadata:
  name: ${Q5_APP}-config
  namespace: ${Q5_NS}
data:
  mode: production
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q5_APP}
  namespace: ${Q5_NS}
  labels: { app: ${Q5_APP} }
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q5_APP} }
  template:
    metadata:
      labels: { app: ${Q5_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 50m, memory: 32Mi }
            limits: { cpu: 250m, memory: 128Mi }
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          livenessProbe:
            tcpSocket: { port: 80 }
            periodSeconds: 5
            failureThreshold: 2
          env:
            - name: APP_MODE
              valueFrom:
                configMapKeyRef: { name: ${Q5_APP}-config, key: mode }
EOF
kubectl -n "${Q5_NS}" get deployment "${Q5_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q5.uid"
chmod 644 "/var/tmp/cka-q5.uid"

case "${Q5_FAULT}" in
  oom-killed)
    kubectl -n "${Q5_NS}" set resources "deployment/${Q5_APP}" --requests=memory=4Mi --limits=memory=4Mi
    ;;
  image-pull)
    kubectl -n "${Q5_NS}" set image "deployment/${Q5_APP}" web=nginx:1.27-alpne
    ;;
  bad-command)
    kubectl -n "${Q5_NS}" patch deployment "${Q5_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","command":["nginx","-g","daemon off; worker_procs 2;"]}]}}}}'
    ;;
  configmap-key)
    kubectl -n "${Q5_NS}" patch configmap "${Q5_APP}-config" --type=json -p '[{"op":"move","from":"/data/mode","path":"/data/mod"}]'
    ;;
  liveness-port)
    kubectl -n "${Q5_NS}" patch deployment "${Q5_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","livenessProbe":{"tcpSocket":{"port":8080}}}]}}}}'
    ;;
  readiness-path)
    kubectl -n "${Q5_NS}" patch deployment "${Q5_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"containers":[{"name":"web","readinessProbe":{"httpGet":{"path":"/healthz"}}}]}}}}'
    ;;
  requests-too-large)
    kubectl -n "${Q5_NS}" set resources "deployment/${Q5_APP}" --requests=cpu=64 --limits=cpu=64
    ;;
  node-selector)
    kubectl -n "${Q5_NS}" patch deployment "${Q5_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"nodeSelector":{"disktype":"ssd"}}}}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q5_NS}" scale "deployment/${Q5_APP}" --replicas=2
sleep 20
